// ── Axioms and basic probability ──────────────────────────────
const outcomes = ['HH', 'HT', 'TH', 'TT']; // two fair coins
const P = event => event.length / outcomes.length;

// Inclusion-exclusion: P(A union B) = P(A) + P(B) - P(A intersect B)
const firstHeads  = outcomes.filter(o => o[0] === 'H');  // HH, HT
const secondHeads = outcomes.filter(o => o[1] === 'H');  // HH, TH
const bothHeads   = outcomes.filter(o => o === 'HH');    // HH

const pUnion = P(firstHeads) + P(secondHeads) - P(bothHeads);
console.log('P(first OR second heads):', pUnion); // 0.75  (= 3/4)

// Complement: P(at least one head) = 1 - P(no heads)
const noHeads = outcomes.filter(o => !o.includes('H')); // TT only
console.log('P(at least one head) via complement:', 1 - P(noHeads)); // 0.75

// ── Conditional probability ───────────────────────────────────
// P(both heads | first coin is heads)
// Sample space shrinks to {HH, HT}
const conditionalBoth = bothHeads.length / firstHeads.length;
console.log('P(both H | first H):', conditionalBoth); // 0.5

// Independence check: P(A and B) === P(A) * P(B) ?
const pFirst  = P(firstHeads);   // 0.5
const pSecond = P(secondHeads);  // 0.5
const pBoth   = P(bothHeads);    // 0.25
console.log('Independent?', Math.abs(pBoth - pFirst * pSecond) < 1e-9); // true

// ── Bayes theorem: spam filter with multiple words ─────────────
function bayesUpdate(prior, likelihood, likelihoodComplement) {
  const pEvidence = likelihood * prior + likelihoodComplement * (1 - prior);
  return (likelihood * prior) / pEvidence;
}

// Start with prior P(spam) = 0.3
let pSpam = 0.3;
// Observe word 'FREE': P(FREE|spam)=0.8, P(FREE|legit)=0.05
pSpam = bayesUpdate(pSpam, 0.8, 0.05);
console.log('After FREE:', pSpam.toFixed(4)); // 0.8727
// Then observe 'CLICK HERE': P(CLICK|spam)=0.6, P(CLICK|legit)=0.1
pSpam = bayesUpdate(pSpam, 0.6, 0.1);
console.log('After FREE+CLICK:', pSpam.toFixed(4)); // 0.9787

// ── Expected value ────────────────────────────────────────────
// Discrete random variable
const distribution = [{val: 1, prob: 0.3}, {val: 2, prob: 0.5}, {val: 5, prob: 0.2}];
const EX = distribution.reduce((sum, {val, prob}) => sum + val * prob, 0);
console.log('E[X]:', EX); // 2.3  (0.3 + 1.0 + 1.0)

// Geometric distribution: expected flips until first head
// E[geometric(p)] = 1/p
const p = 0.5;
console.log('E[flips to first head]:', (1 / p).toFixed(1)); // 2.0

// ── Indicator variable analysis: QuickSort expected comparisons ─
function expectedQuickSortComparisons(n) {
  // E[C] = sum over all pairs i<j of P(i and j compared) = 2/(j-i+1)
  // Equivalent to: 2 * sum_{k=1}^{n-1} (n-k)/(k+1)
  let total = 0;
  for (let i = 1; i <= n; i++) {
    for (let j = i + 1; j <= n; j++) {
      total += 2 / (j - i + 1);
    }
  }
  return total;
}

console.log('E[comps] n=10:  ', expectedQuickSortComparisons(10).toFixed(2));   // 29.24
console.log('E[comps] n=100: ', expectedQuickSortComparisons(100).toFixed(2));  // 943.53
console.log('n*log2(n)*1.386 for n=100:', (100 * Math.log2(100) * 1.386 / Math.LN2 * Math.LN2).toFixed(2));

// ── Monte Carlo: estimate pi using unit circle ─────────────────
function estimatePi(trials, seed) {
  // Linear congruential generator for reproducibility in demos
  let state = seed >>> 0;
  function rand() {
    state = ((state * 1664525) + 1013904223) >>> 0;
    return state / 0xFFFFFFFF;
  }
  let inside = 0;
  for (let i = 0; i < trials; i++) {
    const x = rand() * 2 - 1; // uniform in [-1, 1]
    const y = rand() * 2 - 1;
    if (x * x + y * y <= 1) inside++;
  }
  return 4 * inside / trials; // ratio * 4 = pi estimate
}

console.log('pi estimate  1k trials:', estimatePi(1000, 42).toFixed(4));
console.log('pi estimate 10k trials:', estimatePi(10000, 42).toFixed(4));
console.log('pi estimate 1M trials: ', estimatePi(1000000, 42).toFixed(4));
console.log('Actual pi:             ', Math.PI.toFixed(4));

// ── Linearity of expectation: coupon collector ──────────────────
// Expected number of coupons to collect all n types
// E[T] = n * H(n) where H(n) = 1 + 1/2 + 1/3 + ... + 1/n
function couponCollector(n) {
  let H = 0;
  for (let k = 1; k <= n; k++) H += 1 / k;
  return n * H;
}

console.log('E[coupons] for 6 types (die faces):', couponCollector(6).toFixed(2));   // 14.70
console.log('E[coupons] for 50 types:',            couponCollector(50).toFixed(2));  // 224.96
